def reference(text: str) -> str:
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != " ":
            out.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == " ":
                j += 1
            run = j - i
            if run > 2:
                out.append("-")
            else:
                out.append("_" * run)
            i = j
    return "".join(out)

@given(st.lists(st.integers(min_value=1, max_value=10), min_size=1, max_size=5))
def test_each_space_run_length_maps_correctly(lengths):
    # Build "x<spaces>x<spaces>..." with known run lengths.
    parts = ["x"]
    for L in lengths:
        parts.append(" " * L)
        parts.append("x")
    s = "".join(parts)
    expected_parts = ["x"]
    for L in lengths:
        expected_parts.append("-" if L > 2 else "_" * L)
        expected_parts.append("x")
    assert fix_spaces(s) == "".join(expected_parts)
